def finitePathEquiv (v : Fin N → E) (hv : ∀ i, v i ≠ 0) :
    (Fin N → 𝕜) ≃ₗ[𝕜] FinitePathSpace (𝕜 := 𝕜) v :=
  LinearEquiv.ofInjective (finitePrefixPath (𝕜 := 𝕜) v) (finitePrefixPath_injective v hv)

